    public static void test_sanity() {
        Element element = new Element("p");
        element.text = "test";
        var backup = copy(element);
        _handle_unwanted_tails(element);
        assert element.text == backup.text;
        element.tail = "tail";
        backup = copy(element);
        _handle_unwanted_tails(element);
        assert element.text == "test tail";
        Element div_elem = new Element("div");
        div_elem.add(backup);
        _handle_unwanted_tails(backup);
        assert tostring(div_elem) == "<div><p>test tail</p></div>";

        Element new_elem = new Element("div");
        _wrap_unwanted_siblings_of_div(new_elem);
        assert new_elem != null;

        SubElement p_elem = new SubElement(new_elem, "p");
        _move_element_one_level_up(p_elem);
        assert tostring(new_elem) == "<div><p/></div>";

        Element head = new Element("head");
        _Element result = check_tei(head, "");
        assert result == head;
    }

    public static void test_wrap_unwanted_siblings_of_div_runs() {
        /* Each run of block siblings after a div gets its own wrapper, up to the next div. */
        var body = fromstring("<body><div/><p>a</p><p>b</p><lb/><p>c</p><div/><p>d</p></body>");
        _wrap_unwanted_siblings_of_div(body.get(0));
        assert tostring(body) == "<body><div/><div><p>a</p><p>b</p></div><lb/><div><p>c</p></div><div/><p>d</p></body>";
    }

    public static void test_publisher_added_before_availability_in_publicationStmt() { // noqa: N802 — TEI element name
        // add publisher string
        Element teidoc = new Element("TEI", /* xmlns = */ "http://www.tei-c.org/ns/1.0");
        Document metadata = new Document();
        metadata.sitename = "The Publisher";
        metadata.license = "CC BY-SA 4.0";
        metadata.tags = List.of("cat");
        metadata.categories = List.of("cat");
        _Element header = write_fullheader(teidoc, metadata);
        var publicationstmt = header.indexOf(".//{*}fileDesc/{*}publicationStmt");
        assert publicationstmt.getchildren()
                .stream()
                .map(child -> child.tag)
                .toList() == List.of("publisher", "availability");
        assert publicationstmt.get(0).text == "The Publisher";

        teidoc = new Element("TEI", /* xmlns = */ "http://www.tei-c.org/ns/1.0");
        metadata = new Document();
        metadata.hostname = "example.org";
        metadata.license = "CC BY-SA 4.0";
        metadata.tags = List.of("cat");
        metadata.categories = List.of("cat");
        header = write_fullheader(teidoc, metadata);
        publicationstmt = header.indexOf(".//{*}fileDesc/{*}publicationStmt");
        assert publicationstmt.getchildren()
                .stream()
                .map(child -> child.tag)
                .toList() == List.of("publisher", "availability");
        assert publicationstmt.get(0).text == "example.org";

        teidoc = new Element("TEI", /* xmlns = */ "http://www.tei-c.org/ns/1.0");
        metadata = new Document();
        metadata.hostname = "example.org";
        metadata.sitename = "Example";
        metadata.license = "CC BY-SA 4.0";
        metadata.tags = List.of("cat");
        metadata.categories = List.of("cat");
        header = write_fullheader(teidoc, metadata);
        publicationstmt = header.indexOf(".//{*}fileDesc/{*}publicationStmt");
        assert publicationstmt.getchildren()
                .stream()
                .map(child -> child.tag)
                .toList() == List.of("publisher", "availability");
        assert publicationstmt.get(0).text == "Example (example.org)";
        // no publisher, add "N/A"
        teidoc = new Element("TEI", /* xmlns = */ "http://www.tei-c.org/ns/1.0");
        metadata = new Document();
        metadata.tags = List.of("cat");
        metadata.categories = List.of("cat");
        metadata.license = "CC BY-SA 4.0";
        header = write_fullheader(teidoc, metadata);
        publicationstmt = header.indexOf(".//{*}fileDesc/{*}publicationStmt");
        assert publicationstmt.getchildren()
                .stream()
                .map(child -> child.tag)
                .toList() == List.of("publisher", "availability");
        assert publicationstmt.get(0).text == "N/A";
        // no license, add nothing
        teidoc = new Element("TEI", /* xmlns = */ "http://www.tei-c.org/ns/1.0");
        metadata = new Document();
        metadata.tags = List.of("cat");
        metadata.categories = List.of("cat");
        header = write_fullheader(teidoc, metadata);
        publicationstmt = header.indexOf(".//{*}fileDesc/{*}publicationStmt");
        assert publicationstmt.getchildren().stream().map(child -> child.tag).toList() == List.of("p");
    }

